16:function formatLearnerProfile(state: LearnerState): string {
17:	const topicProfiles = state.topicProfiles.slice(0, 8).map((topic) => {
18:		const retention = topic.retention === null ? "unknown" : `${Math.round(topic.retention * 100)}%`;
19:		const challenge = topic.reportedChallenges.at(-1);
20:		return `- ${topic.topic}: ${topic.status}, mastery ${Math.round(topic.mastery * 100)}%, retention ${retention}${challenge ? `; reported challenge: ${challenge}` : ""}`;
21:	});
22:	return [
23:		`Sessions recorded: ${state.sessionsCount}`,
24:		`Strengths: ${state.strengths.join(", ") || "none established yet"}`,
25:		`Needs review: ${state.weaknesses.join(", ") || "none established yet"}`,
26:		topicProfiles.length > 0 ? `Recent topic evidence:\n${topicProfiles.join("\n")}` : "No demonstrated topic evidence yet.",
27:	].join("\n");
28:}
