30:function nextGoalStep(goal: LearnerGoal): string {
31:	const step = goal.steps.find((candidate) => candidate.status !== "done");
32:	return step ? `${goal.title}: next step is ${step.title}` : `${goal.title}: all planned steps complete`;
33:}
